import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';

const HomePage = () => {
  const location = useLocation();
  const [userInfo, setUserInfo] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchUserInfo = async () => {
      try {
        const accessToken = location.state.accessToken;
        console.log('Access Token:', accessToken);  // Debugging line
        const response = await axios.get('https://devsafa-dev-ed.develop.my.salesforce.com/services/oauth2/userinfo', {
          headers: {
            Authorization: `Bearer ${accessToken}`,
          },
        });
        console.log('User Info Response:', response.data);  // Debugging line
        setUserInfo(response.data);
      } catch (error) {
        console.error('Error fetching user info:', error);
        setError('Failed to load user information.');
      }
    };

    fetchUserInfo();
  }, [location.state.accessToken]);

  return (
    <div>
      <h1>Welcome to the Home Page</h1>
      {error ? (
        <p>{error}</p>
      ) : userInfo ? (
        <div>
          <p>User ID: {userInfo.user_id}</p>
          <p>Username: {userInfo.username}</p>
          <p>Email: {userInfo.email}</p>
          {userInfo.picture && <img src={userInfo.picture} alt="Profile" />}
        </div>
      ) : (
        <p>Loading user information...</p>
      )}
    </div>
  );
};

export default HomePage;
